  "severity": "critical",
  "network_observations": [
    {"ip": "10.108.57.10", "inferred_role": "smtp_relay_phish_delivery_path", "first_seen": "2026-05-12T09:14:07+0200", "last_seen": "2026-05-12T09:21:48+0200"},
    {"ip": "45.137.21.94", "inferred_role": "external_payload_c2_host", "first_seen": "2026-05-12T09:24:31+0200", "last_seen": "2026-05-12T09:26:55+0200"}
  ],
  "attack_progression": [
    {"step": 1, "tactic": "Initial Access — Phishing: Spearphishing Attachment", "technique": "T1566.001", "what_happened": "At 2026-05-12 09:14:07 CEST, a MIME multipart email carrying a macro-enabled Word attachment named Q4_Bonus_Update.docm was delivered through SMTP relay 10.108.57.10 to the corporate finance distribution lists finance.team@corp.local and accounting@corp.local. The senders — noreply@corp-billing.work and invoices@corp-finance.click — are external lookalike domains NOT in the corporate address book. The Content-Type header application/vnd.ms-word.document.macroEnabled.12 plus the OOXML PK magic bytes confirm a genuine macro-enabled Office container, not a renamed text file. The email body explicitly instructs the recipient to 'Enable macros when prompted' — a textbook social-engineering lure. Wazuh rule 91410 'Office macro attachment from external sender' fired with rule.mitre.id T1566.001 at level 12.", "chain_reason": "Wazuh rule 91410 (rule.groups containing 'mail' + 'phishing') fired with rule.description matching 'Office macro attachment from external sender' and rule.mitre.id T1566.001. The lookalike sender domains (corp-billing.work, corp-finance.click) plus the macroEnabled MIME type plus the 'enable macros' lure text is the canonical spearphishing-attachment delivery signature.", "first_seen": "2026-05-12T09:14:07+0200"},
    {"step": 2, "tactic": "Initial Access — Phishing: macro document landed on endpoint", "technique": "T1566.001", "what_happened": "At 09:21:48 CEST, Wazuh File Integrity Monitoring detected the same macro-enabled document written to disk on endpoint WIN-FIN-07 (agent 044, 10.108.57.61) at C:\\Users\\rania.haddad\\Downloads\\Q4_Bonus_Update.docm. This models the finance user rania.haddad saving the attachment from her mail client. FIM rule 52103 'Wazuh FIM: macro-enabled document in Downloads' fired with rule.mitre.id T1566.001 at level 10. A .docm landing in a user Downloads folder is the bridge between email delivery and endpoint execution.", "chain_reason": "Wazuh FIM rule 52103 (rule.groups containing 'syscheck' + 'ossec') fired with syscheck.path ending in Q4_Bonus_Update.docm under a user Downloads directory and rule.mitre.id T1566.001. The same filename appearing in both the email delivery alert (step 1) and the FIM alert (step 2) on a finance-team endpoint links delivery to landing.", "first_seen": "2026-05-12T09:21:48+0200"},
    {"step": 3, "tactic": "Execution — User Execution: Malicious File", "technique": "T1204.002", "what_happened": "At 09:24:09 CEST, Sysmon Event 1 on WIN-FIN-07 recorded WINWORD.EXE (parent command line 'WINWORD.EXE Q4_Bonus_Update.docm') spawning a child powershell.exe with arguments '-nop -w hidden -ep bypass -enc'. An Office productivity application spawning a hidden, execution-policy-bypassed, base64-encoded PowerShell child is not legitimate document behaviour — it is macro-driven code execution. Wazuh rule 92210 'Office application spawned encoded PowerShell child process' fired with rule.mitre.id T1204.002 at level 13.", "chain_reason": "Sysmon Event 1 with data.win.eventdata.parentImage ending in WINWORD.EXE and data.win.eventdata.image ending in powershell.exe and data.win.eventdata.commandLine containing '-enc'. The parent-child relationship WINWORD.EXE -> powershell.exe on the SAME host that received the .docm 2 minutes earlier (step 2) is the macro-execution link.", "first_seen": "2026-05-12T09:24:09+0200"},
    {"step": 4, "tactic": "Command and Control — Application Layer Protocol: Web", "technique": "T1071.001", "what_happened": "At 09:24:31 CEST, ~22 seconds after the PowerShell child spawned, Sysmon Event 3 on WIN-FIN-07 recorded the same powershell.exe making an outbound TCP connection from 10.108.57.61 to external host 45.137.21.94 on port 443. This is the download-cradle reaching out to retrieve the second-stage payload. Wazuh rule 92250 'PowerShell outbound connection to external host after Office spawn' fired with rule.mitre.id T1071.001 at level 12.", "chain_reason": "Sysmon Event 3 with data.win.eventdata.image ending in powershell.exe and data.win.eventdata.destinationIp 45.137.21.94 on the same host WIN-FIN-07, ~22s after the step-3 spawn. The macro -> WINWORD -> powershell -> external 443 sequence is the textbook spearphishing-attachment download-cradle chain.", "first_seen": "2026-05-12T09:24:31+0200"}
  ],
  "time_window": {"start": "2026-05-12T09:14:07+0200", "end": "2026-05-12T09:26:55+0200"},
  "alert_count": 4,
  "unique_steps": 4
}
